16|@HiltViewModel
17|class LoginViewModel @Inject constructor(
18| private val loginUseCase: LoginUseCase,
19|) : ViewModel(), LoginContract.ViewModel {
20|
21| private val _mainState = MutableStateFlow(LoginContract.MainState())
22| override val mainState = _mainState.asStateFlow()
23|
24| private val _effect = EffectMutableSharedFlow<LoginContract.Effect>()
25| override val effect = _effect.asSharedFlow()
26|
27| override fun triggerEvent(event: LoginContract.Event) {
28| when (event) {
29| LoginContract.Event.Init -> {
30| // TODO - check if there's a saved user
31| // TODO - remove mock login data!
32| _mainState.update { it.copy(isInitialized = true, isLoading = false, usernameInput = "demo", passwordInput = "demo", isLoginButtonEnabled = true) }
33| }
34|
35| LoginContract.Event.LoginClicked -> {
36| attemptLogin()
37| }
38|
39| is LoginContract.Event.PasswordUpdated -> {
40| _mainState.update {
41| it.copy(
42| passwordInput = event.input,
43| isLoginButtonEnabled = isInputValid(
44| passwordInput = event.input,
45| ),
46| )
47| }
48| }
49|
50| is LoginContract.Event.UsernameUpdated -> {
51| _mainState.update {
52| it.copy(
53| usernameInput = event.input,
54| isLoginButtonEnabled = isInputValid(
55| usernameInput = event.input,
56| ),
57| )
58| }
59| }
60| }
61| }
62|
63| private fun isInputValid(
64| usernameInput: String? = mainState.value.usernameInput,
65| passwordInput: String? = mainState.value.passwordInput,
66| ): Boolean {
67| return usernameInput?.isNotBlank() == true && passwordInput?.isNotBlank() == true
68| }
69|
70| private fun attemptLogin() = viewModelScope.launch {
71| _mainState.update { it.copy(isLoading = true) }
72| val params = LoginUseCase.LoginParams(
73| mainState.value.usernameInput ?: "",
74| mainState.value.passwordInput ?: "",
75| )
76| val result = loginUseCase(params)
77| _mainState.update { it.copy(isLoading = false) }
78| when (result) {
79| is Result.Error -> handleLoginError(error = result.error)
80| is Result.Success -> {
81| _effect.tryEmit(LoginContract.Effect.GoToHome)
82| }
83| }
84| }
85|
86| private fun handleLoginError(error: LoginUseCase.FeatureError) {
87| _effect.tryEmit(
88| when (error) {
89| LoginUseCase.FeatureError.GenericError -> LoginContract.Effect.ShowGenericError
90| LoginUseCase.FeatureError.InvalidCredentials -> LoginContract.Effect.ShowInvalidCredentialsError
91| },
92| )
93| }
