emove(PreferencesKeys.BIOMETRIC_IV)\n preferences.remove(PreferencesKeys.BIOMETRIC_ENABLED)\n }\n }\n\n override fun clearUserData() {\n // No-op - no user data to clear\n }\n}"}"}}]},{"role":"tool","name":"edit","tool_call_id":"toolu_01CxtKYTJ9AmHitNDKB2fr3V","content":"The file C:\Users\afane\StudioProjects\myfin-android\android\app\src\main\java\com\afaneca\myfin\data\source\DataStorePersistentDataSource.kt has been updated.

