import androidx.compose.foundation.Image
import androidx.compose.foundation.layout.*
import androidx.compose.material3.*
import androidx.compose.runtime.*
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.platform.LocalContext
import androidx.compose.ui.res.painterResource
import androidx.compose.ui.res.stringResource
import androidx.compose.ui.text.style.TextAlign
import androidx.compose.ui.unit.dp
import androidx.fragment.app.FragmentActivity
import androidx.hilt.lifecycle.viewmodel.compose.hiltViewModel
import androidx.lifecycle.Lifecycle
import androidx.lifecycle.compose.LocalLifecycleOwner
import androidx.lifecycle.compose.collectAsStateWithLifecycle
import androidx.lifecycle.flowWithLifecycle
import com.afaneca.myfin.R
import com.afaneca.myfin.ui.common.MFScaffold

@Composable
fun BiometricSetupScreen(
 username: String,
 password: String,
 viewModel: BiometricSetupViewModel = hiltViewModel(),
 goToHome: () -> Unit,
) {
 val context = LocalContext.current
 val lifecycleOwner = LocalLifecycleOwner.current
 val uiState by viewModel.mainState.collectAsStateWithLifecycle()
 val snackbarHostState = remember { SnackbarHostState() }

 suspend fun showBiometricNotAvailableError() {
 snackbarHostState.showSnackbar(
 message = context.getString(R.string.biometric_not_available),
 withDismissAction = true
 )
 }

 suspend fun showBiometricNotEnrolledError() {
 snackbarHostState.showSnackbar(
 message = context.getString(R.string.biometric_not_enrolled),
 withDismissAction = true
 )
 }

 suspend fun showBiometricError() {
 snackbarHostState.showSnackbar(
 message = context.getString(R.string.biometric_error),
 withDismissAction = true
 )
 }

 LaunchedEffect(Unit) {
 viewModel.triggerEvent(BiometricSetupContract.Event.Init(username, password))

 viewModel.effect.flowWithLifecycle(lifecycleOwner.lifecycle, Lifecycle.State.STARTED)
 .collect { effect ->
 when (effect) {
 BiometricSetupContract.Effect.GoToHome -> goToHome()
 BiometricSetupContract.Effect.ShowBiometricNotAvailableError ->
 showBiometricNotAvailableError()
 BiometricSetupContract.Effect.ShowBiometricNotEnrolledError ->
 showBiometricNotEnrolledError()
 BiometricSetupContract.Effect.ShowBiometricError ->
 showBiometricError()
 }
 }
 }

 MFScaffold(
 title = "",
 snackbarHost = { SnackbarHost(snackbarHostState) },
 ) { padding ->
 BiometricSetupContent(
 uiState = uiState,
 modifier = Modifier
 .padding(padding)
 .consumeWindowInsets(padding),
 onEnableClicked = {
 if (context is FragmentActivity) {
 viewModel.performBiometricSetup(context)
 }
 },
 onSkipClicked = {
 viewModel.triggerEvent(BiometricSetupContract.Event.SkipClicked)
 }
 )
 }
}

@Composable
private fun BiometricSetupContent(
 uiState: BiometricSetupContract.MainState,
 modifier: Modifier = Modifier,
 onEnableClicked: () -> Unit,
 onSkipClicked: () -> Unit,
) {
 Box(
 modifier = modifier.fillMaxSize(),
 contentAlignment = Alignment.Center
 ) {
 Column(
 modifier = Modifier
 .fillMaxWidth()
 .padding(32.dp),
 horizontalAlignment = Alignment.CenterHorizontally,
 verticalArrangement = Arrangement.spacedBy(24.dp)
 ) {
 // Fingerprint icon
 Icon(
 painter = painterResource(id = R.drawable.fingerprint_24),
 contentDescription = null,
 modifier = Modifier.size(80.dp),
 tint = MaterialTheme.colorScheme.primary
 )

 // Title
 Text(
 text = stringResource(R.string.biometric_setup_prompt_title),
 style = MaterialTheme.typography.headlineMedium,
 textAlign = TextAlign.Center
 )

 // Description
 Text(
 text = stringResource(R.string.biometric_setup_prompt_description),
 style = MaterialTheme.typography.bodyLarge,
 textAlign = TextAlign.Center,
 color = MaterialTheme.colorScheme.onSurfaceVariant
 )

 Spacer(modifier = Modifier.height(16.dp))

 // Enable button
 Button(
 onClick = onEnableClicked,
 modifier = Modifier.fillMaxWidth(),
 enabled = !uiState.isLoading && uiState.isBiometricAvailable
 ) {
 if (uiState.isLoading) {
 CircularProgressIndicator(
 modifier = Modifier.size(20.dp),
 strokeWidth = 2.dp,
 color = MaterialTheme.colorScheme.onPrimary
 )
 } else {
 Text(stringResource(R.string.biometric_enable))
 }
 }

 // Skip button
 TextButton(
 onClick = onSkipClicked,
 modifier = Modifier.fillMaxWidth(),
 enabled = !uiState.isLoading
 ) {
 Text(stringResource(R.string.biometric_skip))
 }
 }
 }
}
","ranges":[],"type":"current_file"},{"file_path":"app/src/main/java/com/afaneca/myfin/ui/main/MainActivity.kt","code_text":"package com.afaneca.myfin.ui.main

import android.os.Bundle
import androidx.activity.ComponentActivity
import androidx.activity.compose.setContent
import androidx.activity.enableEdgeToEdge
import androidx.compose.foundation.layout.Box
import androidx.compose.foundation.layout.fillMaxSize
import androidx.compose.material3.Text
import androidx.compose.material3.ModalDrawerSheet
import androidx.compose.material3.ModalNavigationDrawer
import androidx.compose.material3.NavigationDrawerItem
import androidx.compose.material3.rememberDrawerState
import androidx.compose.material3.DrawerValue
import androidx.compose.material3.Icon
import androidx.compose.material3.MaterialTheme
import androidx.compose.material3.NavigationDrawerItemDefaults
import androidx.compose.runtime.CompositionLocalProvider
import androidx.compose.runtime.LaunchedEffect
import androidx.compose.runtime.getValue
import androidx.compose.runtime.remember
import androidx.compose.runtime.rememberCoroutineScope
import androidx.compose.ui.Modifier
import androidx.compose.ui.res.painterResource
import androidx.compose.ui.res.stringResource
import androidx.fragment.app.FragmentActivity
import androidx.hilt.lifecycle.viewmodel.compose.hiltViewModel
import androidx.lifecycle.Lifecycle
import androidx.lifecycle.compose.LocalLifecycleOwner
import androidx.lifecycle.compose.collectAsStateWithLifecycle
import androidx.lifecycle.flowWithLifecycle
import androidx.navigation3.runtime.EntryProviderScope
import androidx.navigation3.runtime.NavKey
import androidx.navigation3.runtime.entryProvider
import com.afaneca.myfin.R
import com.afaneca.myfin.ui.common.GlobalLoadingOverlay
import com.afaneca.myfin.ui.common.MFModalNavigationDrawer
import com.afaneca.myfin.ui.common.MFNavDisplay
import com.afaneca.myfin.ui.common.nav.Navigator
import com.afaneca.myfin.ui.common.nav.rememberNavigationState
import com.afaneca.myfin.ui.common.nav.toEntries
import com.afaneca.myfin.ui.dashboard.DashboardScreen
import com.afaneca.myfin.ui.login.LoginScreen
import com.afaneca.myfin.ui.main.MainContract.LocalLoadingState
import com.afaneca.myfin.ui.onboarding.BiometricSetupScreen
import com.afaneca.myfin.ui.settings.SettingsScreen
import com.afaneca.myfin.ui.theme.AppTheme
import com.afaneca.myfin.ui.transactions.list.TransactionListScreen
import dagger.hilt.android.AndroidEntryPoint
import kotlinx.coroutines.flow.launchIn
import kotlinx.coroutines.flow.onEach
import kotlinx.coroutines.launch
import kotlinx.serialization.Serializable

sealed interface AppRoute : NavKey {
 @Serializable
 data object Login : AppRoute

 @Serializable
 data class BiometricSetup(val username: String, val password: String) : AppRoute

 @Serializable
 data object Onboarding : AppRoute

 @Serializable
 data object Settings : AppRoute

 @Serializable
 data object Home : AppRoute

 @Serializable
 data object Transactions : AppRoute
}

@AndroidEntryPoint
class MainActivity : FragmentActivity() {

 override fun onCreate(savedInstanceState: Bundle?) {
 super.onCreate(savedInstanceState)
 enableEdgeToEdge()
 setContent {
 val viewModel: MainViewModel = hiltViewModel()
 val lifecycleOwner = LocalLifecycleOwner.current
 val uiState by viewModel.mainState.collectAsStateWithLifecycle()
 val navigationState = rememberNavigationState(
 startRoute = AppRoute.Login,
 topLevelRoutes = setOf(
 AppRoute.Login,
 AppRoute.Home,
 ),
 )

 val navigator = remember { Navigator(navigationState) }

 val isPrivateRoute = when (navigationState.topLevelRoute) {
 AppRoute.Login, AppRoute.Settings, AppRoute.Onboarding -> false
 is AppRoute.BiometricSetup -> false
 else -> true
 }

 val drawerState = rememberDrawerState(DrawerValue.Closed)
 val scope = rememberCoroutineScope()

 LaunchedEffect(Unit) {
 viewModel.triggerEvent(MainContract.Event.Init)

 viewModel.effect.flowWithLifecycle(
 lifecycleOwner.lifecycle,
 Lifecycle.State.STARTED,
 )
 .onEach { effect ->
 when (effect) {
 MainContract.Effect.OpenNavigationDrawer -> {
 drawerState.open()
 }

 MainContract.Effect.GoToLogin -> {
 navigator.navigate(
 route = AppRoute.Login,
 removeCurrentFromBackStack = true,
 )
 }
 }
 }.launchIn(this)
 }

 fun openNavigationDrawer() {
 viewModel.triggerEvent(MainContract.Event.NavDrawerIconClicked)
 }

 AppTheme(
 dynamicColor = uiState.useDynamicTheme,
 ) {

 CompositionLocalProvider(
 LocalLoadingState provides MainContract.LoadingState(
 isLoading = uiState.isLoading,
 setLoading = { viewModel.triggerEvent(MainContract.Event.UpdateLoading(it)) },
 ),
 ) {
 Box(modifier = Modifier.fillMaxSize()) {
 MFModalNavigationDrawer(
 drawerState = drawerState,
 gesturesEnabled = isPrivateRoute,
 balanceDigest = uiState.balanceDigest,
 itemContent = {
 NavigationDrawerItem(
 icon = {
 Icon(
 painter = painterResource(R.drawable.dashboard_24),
 contentDescription = stringResource(R.string.dashboard),
 )
 },
 label = { Text(stringResource(R.string.dashboard)) },
 selected = navigationState.currentRoute == AppRoute.Home,
 onClick = {
 navigator.navigate(AppRoute.Home)
 scope.launch { drawerState.close() }
 },
 )
 NavigationDrawerItem(
 icon = {
 Icon(
 painter = painterResource(R.drawable.list_alt_24),
 contentDescription = stringResource(R.string.transactions),
 )
 },
 label = { Text(stringResource(R.string.transactions)) },
 selected = navigationState.currentRoute == AppRoute.Transactions,
 onClick = {
 navigator.navigate(AppRoute.Transactions)
 scope.launch { drawerState.close() }
 },
 )
 NavigationDrawerItem(
 icon = {
 Icon(
 painter = painterResource(R.drawable.logout_24),
 contentDescription = stringResource(R.string.logout),
 )
 },
 label = { Text(stringResource(R.string.logout)) },
 selected = false,
 onClick = {
 viewModel.triggerEvent(MainContract.Event.LogoutClicked)
 scope.launch { drawerState.close() }
 },
 colors = NavigationDrawerItemDefaults.colors(
 unselectedTextColor = MaterialTheme.colorScheme.error,
 unselectedIconColor = MaterialTheme.colorScheme.error,
 ),
 )
 },
 ) {
 val entryProvider = entryProvider {
 publicNav(navigator = navigator)
 privateNav(
 openNavigationDrawer = { openNavigationDrawer() },
 goToSettings = { navigator.navigate(AppRoute.Settings) },
 goToTransactions = { navigator.navigate(AppRoute.Transactions) },
 goToAccounts = { /* TODO */ },
 goToBudgets = { /* TODO */ },
 )
 }

 MFNavDisplay(
 entries = navigationState.toEntries(entryProvider),
 onBack = {
 if (drawerState.isOpen) {
 scope.launch { drawerState.close() }
 return@MFNavDisplay
 }
 if (!navigator.goBack()) {
 finish()
 }
 },
 )
 }

 GlobalLoadingOverlay(isLoading = uiState.isLoading)
 }
 }
 }
 }
 }

 private fun EntryProviderScope<NavKey>.publicNav(navigator: Navigator) {
 entry<AppRoute.Login> { key ->
 LoginScreen(
 goToHome = {
 navigator.navigate(route = AppRoute.Home, removeCurrentFromBackStack = true)
 },
 goToBiometricSetup = { username, password ->
 navigator.navigate(
 route = AppRoute.BiometricSetup(username, password),
 removeCurrentFromBackStack = false
 )
 },
 showError = {},
 goToSettings = { navigator.navigate(AppRoute.Settings) },
 )
 }

 entry<AppRoute.BiometricSetup> { key ->
 BiometricSetupScreen(
 username = key.username,
 password = key.password,
 goToHome = {
 navigator.navigate(route = AppRoute.Home, removeCurrentFromBackStack = true)
 }
 )
 }

 entry<AppRoute.Settings> { key ->
 SettingsScreen()
 }
 }

 private fun EntryProviderScope<NavKey>.privateNav(
 openNavigationDrawer: () -> Unit,
 goToSettings: () -> Unit,
 goToTransactions: () -> Unit,
 goToAccounts: () -> Unit,
 goToBudgets: () -> Unit,
 ) {
 entry<AppRoute.Home> { key ->
 DashboardScreen(
 openNavigationDrawer = openNavigationDrawer,
 goToSettings = goToSettings,
 goToTransactions = goToTransactions,
 goToAccounts = goToAccounts,
 goToBudgets = goToBudgets,
 )
 }
 entry<AppRoute.Transactions> { key ->
 TransactionListScreen(
 openNavigationDrawer = openNavigationDrawer,
 goToSettings = goToSettings,
 )
 }
 }
}
