Since the class is `@Singleton`, the lazy initialization is perfect - it ensures the keystore is loaded only once when first needed, rather than eagerly when the singleton is created. "}]},{"role":"user","content":[{"type":"text","text":"could you improve error handling?"}],"context":[{"file_path":"app/src/main/java/com/afaneca/myfin/data/biometric/CryptoManager.kt","code_text":"package com.afaneca.myfin.data.biometric

import android.os.Build
import android.security.keystore.KeyGenParameterSpec
import android.security.keystore.KeyPermanentlyInvalidatedException
import android.security.keystore.KeyProperties
import java.security.KeyStore
import javax.crypto.Cipher
import javax.crypto.KeyGenerator
import javax.crypto.SecretKey
import javax.crypto.spec.GCMParameterSpec
import android.util.Base64
import javax.inject.Inject
import javax.inject.Singleton

@Singleton
class CryptoManager @Inject constructor() {

 private val keyStore by lazy {
 KeyStore.getInstance(KEYSTORE_PROVIDER).apply {
 load(null)
 }
 }

 companion object {
 private const val KEYSTORE_PROVIDER = "AndroidKeyStore"
 private const val KEY_ALIAS = "MyFinBiometricKey"
 private const val TRANSFORMATION = "${KeyProperties.KEY_ALGORITHM_AES}/${KeyProperties.BLOCK_MODE_GCM}/${KeyProperties.ENCRYPTION_PADDING_NONE}"
 private const val GCM_TAG_LENGTH = 128
 }

 fun getOrCreateKey(): SecretKey {
 if (!keyStore.containsAlias(KEY_ALIAS)) {
 val keyGenerator = KeyGenerator.getInstance(
 KeyProperties.KEY_ALGORITHM_AES,
 KEYSTORE_PROVIDER
 )

 val keyGenParameterSpec = KeyGenParameterSpec.Builder(
 KEY_ALIAS,
 KeyProperties.PURPOSE_ENCRYPT or KeyProperties.PURPOSE_DECRYPT
 ).apply {
 setBlockModes(KeyProperties.BLOCK_MODE_GCM)
 setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE)
 setUserAuthenticationRequired(true)

 // Use different APIs based on Android version
 if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.R) {
 // API 30+ - Use new method with biometric strong requirement
 setUserAuthenticationParameters(
 0, // timeout in seconds, 0 means auth required for each use
 KeyProperties.AUTH_BIOMETRIC_STRONG
 )
 } else {
 // API 24-29 - Use deprecated method but still works
 @Suppress("DEPRECATION")
 setUserAuthenticationValidityDurationSeconds(-1) // -1 means auth required for each use
 }
 }.build()

 keyGenerator.init(keyGenParameterSpec)
 keyGenerator.generateKey()
 }

 return keyStore.getKey(KEY_ALIAS, null) as SecretKey
 }

 fun getEncryptCipher(): Cipher {
 try {
 val cipher = Cipher.getInstance(TRANSFORMATION)
 cipher.init(Cipher.ENCRYPT_MODE, getOrCreateKey())
 return cipher
 } catch (e: KeyPermanentlyInvalidatedException) {
 deleteKey()
 throw e
 }
 }

 fun getDecryptCipher(iv: ByteArray): Cipher {
 try{
 val cipher = Cipher.getInstance(TRANSFORMATION)
 val spec = GCMParameterSpec(GCM_TAG_LENGTH, iv)
 cipher.init(Cipher.DECRYPT_MODE, getOrCreateKey(), spec)
 return cipher
 } catch (e: KeyPermanentlyInvalidatedException) {
 deleteKey()
 throw e
 }
 }

 fun encryptData(plaintext: String, cipher: Cipher): Pair<String, String> {
 val encryptedBytes = cipher.doFinal(plaintext.toByteArray(Charsets.UTF_8))
 val iv = cipher.iv

 return Pair(
 Base64.encodeToString(encryptedBytes, Base64.NO_WRAP),
 Base64.encodeToString(iv, Base64.NO_WRAP)
 )
 }

 fun deleteKey() {
 if (keyStore.containsAlias(KEY_ALIAS)) {
 keyStore.deleteEntry(KEY_ALIAS)
 }
 }
}
