 35| BiometricSetupContract.Event.SkipClicked -> skip()
 36| }
 37| }
 38|
 39| private fun init(username: String, password: String) {
 40| if (mainState.value.isInitialized) return
 41|
 42| storedUsername = username
 43| storedPassword = password
 44|
 45| val isBiometricAvailable = biometricGateway.isBiometricAvailable() &&
 46| biometricGateway.isBiometricEnrolled()
 47|
 48| _mainState.update {
 49| it.copy(
 50| isInitialized = true,
 51| isBiometricAvailable = isBiometricAvailable
 52| )
 53| }
 54|
 55| // If biometric is not available, skip to home automatically
 56| if (!isBiometricAvailable) {
 57| skip()
 58| }
 59| }
 60|
 61| private fun enableBiometric() {
 62| // This will be called from the UI with the activity reference
 63| // The actual biometric prompt will be triggered from the composable
 64| }
 65|
 66| fun performBiometricSetup(activity: FragmentActivity) = viewModelScope.launch {
 67| _mainState.update { it.copy(isLoading = true) }
 68|
 69| val result = biometricGateway.saveBiometricCredentials(
 70| username = storedUsername,
 71| password = storedPassword,
 72| activity = activity
 73| )
 74|
 75| _mainState.update { it.copy(isLoading = false) }
 76|
 77| when (result) {
 78| is BiometricAuthResult.Success -> {
 79| _effect.tryEmit(BiometricSetupContract.Effect.GoToHome)
 80| }
 81| is BiometricAuthResult.EncryptionSuccess -> {
 82| // This shouldn't happen as repository converts it, but handle it anyway
 83| _effect.tryEmit(BiometricSetupContract.Effect.GoToHome)
 84| }
 85| BiometricAuthResult.NotAvailable -> {
 86| _effect.tryEmit(BiometricSetupContract.Effect.ShowBiometricNotAvailableError)
 87| }
 88| BiometricAuthResult.NotEnrolled -> {
 89| _effect.tryEmit(BiometricSetupContract.Effect.ShowBiometricNotEnrolledError)
 90| }
 91| BiometricAuthResult.Cancelled -> {
 92| // User cancelled, do nothing and let them retry
 93| }
 94| is BiometricAuthResult.Failure -> {
 95| _effect.tryEmit(BiometricSetupContract.Effect.ShowBiometricError)
 96| }
 97| }
 98| }
 99|
100| private fun skip() {
101| _effect.tryEmit(BiometricSetupContract.Effect.GoToHome)
102| }
103|}
