 2|
 3|import com.afaneca.myfin.domain.error.DomainError
 4|import com.afaneca.myfin.domain.model.LoginResult
 5|import com.afaneca.myfin.domain.repository.AuthGateway
 6|import com.afaneca.myfin.domain.common.Result
 7|import com.afaneca.myfin.domain.repository.AccountGateway
 8|import javax.inject.Inject
 9|
10|class LoginUseCase @Inject constructor(
11| private val authGateway: AuthGateway,
12| private val accountGateway: AccountGateway,
13|) : BaseUseCase<LoginUseCase.LoginParams, LoginResult, LoginUseCase.FeatureError> {
14|
15| data class LoginParams(val username: String, val password: String)
16|
17| override suspend operator fun invoke(params: LoginParams): Result<LoginResult, FeatureError> {
18| return when (val result = authGateway.login(params.username, params.password)) {
19| is Result.Success -> {
20| accountGateway.refreshBalanceDigest(result.data.accounts)
21| Result.Success(result.data)
22| }
23|
24| is Result.Error -> {
25| val loginError = when (result.error) {
26| DomainError.Unauthorized -> FeatureError.InvalidCredentials
27| else -> FeatureError.GenericError
28| }
29| Result.Error(loginError)
30| }
31| }
32| }
33|
34| sealed interface FeatureError {
35| data object InvalidCredentials : FeatureError
36| data object GenericError : FeatureError
37| }
38|}
