 2|
 3|import androidx.fragment.app.FragmentActivity
 4|import androidx.lifecycle.ViewModel
 5|import androidx.lifecycle.viewModelScope
 6|import com.afaneca.myfin.data.biometric.BiometricAuthManager
 7|import com.afaneca.myfin.domain.model.BiometricAuthResult
 8|import com.afaneca.myfin.domain.repository.BiometricGateway
 9|import com.afaneca.myfin.domain.usecase.LoginUseCase
 10|import com.afaneca.myfin.domain.common.Result
 11|import com.afaneca.myfin.ui.common.EffectMutableSharedFlow
 12|import dagger.hilt.android.lifecycle.HiltViewModel
 13|import kotlinx.coroutines.flow.MutableStateFlow
 14|import kotlinx.coroutines.flow.asSharedFlow
 15|import kotlinx.coroutines.flow.asStateFlow
 16|import kotlinx.coroutines.flow.update
 17|import kotlinx.coroutines.launch
 18|import javax.inject.Inject
 19|
 20|@HiltViewModel
 21|class LoginViewModel @Inject constructor(
 22| private val loginUseCase: LoginUseCase,
 23| private val biometricGateway: BiometricGateway,
 24|) : ViewModel(), LoginContract.ViewModel {
 25|
 26| private val _mainState = MutableStateFlow(LoginContract.MainState())
 27| override val mainState = _mainState.asStateFlow()
 28|
 29| private val _effect = EffectMutableSharedFlow<LoginContract.Effect>()
 30| override val effect = _effect.asSharedFlow()
 31|
 32| override fun triggerEvent(event: LoginContract.Event) {
 33| when (event) {
 34| LoginContract.Event.Init -> init()
 35|
 36| LoginContract.Event.LoginClicked -> {
 37| attemptLogin()
 38| }
 39|
 40| LoginContract.Event.BiometricLoginClicked -> {
 41| // Biometric login will be triggered from the UI with activity reference
 42| }
 43|
 44| is LoginContract.Event.PasswordUpdated -> {
 45| _mainState.update {
 46| it.copy(
 47| passwordInput = event.input,
 48| isLoginButtonEnabled = isInputValid(
 49| passwordInput = event.input,
 50| ),
 51| )
 52| }
 53| }
 54|
 55| is LoginContract.Event.UsernameUpdated -> {
 56| _mainState.update {
 57| it.copy(
 58| usernameInput = event.input,
 59| isLoginButtonEnabled = isInputValid(
 60| usernameInput = event.input,
 61| ),
 62| )
 63| }
 64| }
 65| }
 66| }
 67|
 68| private fun init() = viewModelScope.launch {
 69| val isBiometricAvailable = biometricGateway.isBiometricAvailable() &&
 70| biometricGateway.isBiometricEnrolled()
 71| val isBiometricEnabled = biometricGateway.isBiometricEnabled()
 72|
 73| // TODO - remove mock login data!
 74| _mainState.update {
 75| it.copy(
 76| isInitialized = true,
 77| isLoading = false,
 78| usernameInput = "demo",
 79| passwordInput = "demo",
 80| isLoginButtonEnabled = true,
 81| isBiometricAvailable = isBiometricAvailable,
 82| isBiometricEnabled = isBiometricEnabled,
 83| )
 84| }
 85| }
 86|
 87| private fun isInputValid(
 88| usernameInput: String? = mainState.value.usernameInput,
 89| passwordInput: String? = mainState.value.passwordInput,
 90| ): Boolean {
 91| return usernameInput?.isNotBlank() == true && passwordInput?.isNotBlank() == true
 92| }
 93|
 94| private fun attemptLogin() = viewModelScope.launch {
 95| _mainState.update { it.copy(isLoading = true) }
 96| val username = mainState.value.usernameInput ?: ""
 97| val password = mainState.value.passwordInput ?: ""
 98| val params = LoginUseCase.LoginParams(username, password)
 99| val result = loginUseCase(params)
100| _mainState.update { it.copy(isLoading = false) }
101| when (result) {
102| is Result.Error -> handleLoginError(error = result.error)
103| is Result.Success -> {
104| // Check if this is first login (biometric not enabled yet)
105| val isBiometricEnabled = biometricGateway.isBiometricEnabled()
106| if (!isBiometricEnabled && biometricGateway.isBiometricAvailable()) {
107| // First login - redirect to biometric setup
108| _mainState.update { it.copy(isFirstLogin = true) }
109| _effect.tryEmit(LoginContract.Effect.GoToBiometricSetup(username, password))
110| } else {
111| // Not first login or biometric not available - go directly to home
112| _effect.tryEmit(LoginContract.Effect.GoToHome)
113| }
114| }
115| }
116| }
117|
118| fun performBiometricLogin(activity: FragmentActivity) = viewModelScope.launch {
119| _mainState.update { it.copy(isLoading = true) }
120|
121| val credentials = biometricGateway.getBiometricCredentials()
122| if (credentials == null) {
123| _mainState.update { it.copy(isLoading = false) }
124| _effect.tryEmit(LoginContract.Effect.ShowBiometricError)
125| return@launch
126| }
127|
128| val authResult = biometricGateway.authenticateWithBiometric(activity)
129|
130| when (authResult) {
131| is BiometricAuthResult.Success -> {
132| val params = LoginUseCase.LoginParams(
133| username = credentials.username,
134| password = authResult.data
135| )
136| val result = loginUseCase(params)
137| _mainState.update { it.copy(isLoading = false) }
138|
139| when (result) {
140| is Result.Error -> handleLoginError(error = result.error)
141| is Result.Success -> {
142| _effect.tryEmit(LoginContract.Effect.GoToHome)
143| }
144| }
145| }
146| BiometricAuthResult.Cancelled -> {
147| _mainState.update { it.copy(isLoading = false) }
148| // User cancelled, do nothing
149| }
150| is BiometricAuthResult.EncryptionSuccess -> {
151| // This shouldn't happen in login flow, but handle it
152| _mainState.update { it.copy(isLoading = false) }
153| _effect.tryEmit(LoginContract.Effect.ShowBiometricError)
154| }
155| is BiometricAuthResult.Failure -> {
156| _mainState.update { it.copy(isLoading = false) }
157| // Check if key was invalidated
158| if (authResult.errorCode == BiometricAuthManager.ERROR_KEY_INVALIDATED) {
159| // Biometric credentials were automatically cleared, show special message
160| _effect.tryEmit(LoginContract.Effect.ShowBiometricKeyInvalidatedError)
161| } else {
162| _effect.tryEmit(LoginContract.Effect.ShowBiometricError)
163| }
164| }
165| else -> {
166| _mainState.update { it.copy(isLoading = false) }
167| _effect.tryEmit(LoginContract.Effect.ShowBiometricError)
168| }
169| }
170| }
171|
172| private fun handleLoginError(error: LoginUseCase.FeatureError) {
173| _effect.tryEmit(
174| when (error) {
175| LoginUseCase.FeatureError.GenericError -> LoginContract.Effect.ShowGenericError
176| LoginUseCase.FeatureError.InvalidCredentials -> LoginContract.Effect.ShowInvalidCredentialsError
177| },
178| )
179| }
180|}
181|
