yUseCase\nimport com.afaneca.myfin.domain.usecase.GetBiometricCredentialsUseCase\nimport com.afaneca.myfin.domain.usecase.IsBiometricEnabledUseCase\nimport com.afaneca.myfin.domain.usecase.LoginUseCase\nimport com.afaneca.myfin.domain.common.Result\nimport com.afaneca.myfin.ui.common.EffectMutableSharedFlow\nimport dagger.hilt.android.lifecycle.HiltViewModel\nimport kotlinx.coroutines.flow.MutableStateFlow\nimport kotlinx.coroutines.flow.asSharedFlow\nimport kotlinx.coroutines.flow.asStateFlow\nimport kotlinx.coroutines.flow.update\nimport kotlinx.coroutines.launch\nimport javax.inject.Inject\n\n@HiltViewModel\nclass LoginViewModel @Inject constructor(\n private val loginUseCase: LoginUseCase,\n private val checkBiometricAvailabilityUseCase: CheckBiometricAvailabilityUseCase,\n private val isBiometricEnabledUseCase: IsBiometricEnabledUseCase,\n private val getBiometricCredentialsUseCase: GetBiometricCredentialsUseCase,\n private val authenticateWithBiometricUseCase: AuthenticateWithBiometricUseCase,\n) : ViewModel(), LoginContract.ViewModel {"}"}},{"id":"toolu_01PshstUh1H787Y8fCSsnnZB","type":"function","function":{"name":"edit","arguments":"{"file_path": "C:/Users/afane/StudioProjects/myfin-android/android/app/src/main/java/com/afaneca/myfin/ui/login/LoginViewModel.kt", "old_string": " private fun init() = viewModelScope.launch {\n val isBiometricAvailable = biometricGateway.isBiometricAvailable() &&\n biometricGateway.isBiometricEnrolled()\n val isBiometricEnabled = biometricGateway.isBiometricEnabled()\n\n // TODO - remove mock login data!\n _mainState.update {\n it.copy(\n isInitialized = true,\n isLoading = false,\n usernameInput = \"demo\",\n passwordInput = \"demo\",\n isLoginButtonEnabled = true,\n isBiometricAvailable = isBiometricAvailable,\n isBiometricEnabled = isBiometricEnabled,\n )\n }\n }", "new_string": " private fun init() = viewModelScope.launch {\n val availabilityResult = checkBiometricAvailabilityUseCase(Unit)\n val isBiometricAvailable = when (availabilityResult) {\n is Result.Success -> availabilityResult.data.canUseBiometric\n is Result.Error -> false\n }\n \n val enabledResult = isBiometricEnabledUseCase(Unit)\n val isBiometricEnabled = when (enabledResult) {\n is Result.Success -> enabledResult.data\n is Result.Error -> false\n }\n\n // TODO - remove mock login data!\n _mainState.update {\n it.copy(\n isInitialized = true,\n isLoading = false,\n usernameInput = \"demo\",\n passwordInput = \"demo\",\n isLoginButtonEnabled = true,\n isBiometricAvailable = isBiometricAvailable,\n isBiometricEnabled = isBiometricEnabled,\n )\n }\n }"}"}},{"id":"toolu_0194e3U3oAmxHoRU5rNnJKnk","type":"function","function":{"name":"edit","arguments":"{"file_path": "C:/Users/afane/StudioProjects/myfin-android/android/app/src/main/java/com/afaneca/myfin/ui/login/LoginViewModel.kt", "old_string": " private fun attemptLogin() = viewModelScope.launch {\n _mainState.update { it.copy(isLoading = true) }\n val username = mainState.value.usernameInput ?: \"\"\n val password = mainState.value.passwordInput ?: \"\"\n val params = LoginUseCase.LoginParams(username, password)\n val result = loginUseCase(params)\n _mainState.update { it.copy(isLoading = false) }\n when (result) {\n is Result.Error -> handleLoginError(error = result.error)\n is Result.Success -> {\n // Check if this is first login (biometric not enabled yet)\n val isBiometricEnabled = biometricGateway.isBiometricEnabled()\n if (!isBiometricEnabled && biometricGateway.isBiometricAvailable()) {\n // First login - redirect to biometric setup\n _mainState.update { it.copy(isFirstLogin = true) }\n _effect.tryEmit(LoginContract.Effect.GoToBiometricSetup(username, password))\n } else {\n // Not first login or biometric not available - go directly to home\n _effect.tryEmit(LoginContract.Effect.GoToHome)\n }\n }\n }\n }", "new_string": " private fun attemptLogin() = viewModelScope.launch {\n _mainState.update { it.copy(isLoading = true) }\n val username = mainState.value.usernameInput ?: \"\"\n val password = mainState.value.passwordInput ?: \"\"\n val params = LoginUseCase.LoginParams(username, password)\n val result = loginUseCase(params)\n _mainState.update { it.copy(isLoading = false) }\n when (result) {\n is Result.Error -> handleLoginError(error = result.error)\n is Result.Success -> {\n // Check if this is first login (biometric not enabled yet)\n val enabledResult = isBiometricEnabledUseCase(Unit)\n val isBiometricEnabled = when (enabledResult) {\n is Result.Success -> enabledResult.data\n is Result.Error -> false\n }\n \n val availabilityResult = checkBiometricAvailabilityUseCase(Unit)\n val canUseBiometric = when (availabilityResult) {\n is Result.Success -> availabilityResult.data.canUseBiometric\n is Result.Error -> false\n }\n \n if (!isBiometricEnabled && canUseBiometric) {\n // First login - redirect to biometric setup\n _mainState.update { it.copy(isFirstLogin = true) }\n _effect.tryEmit(LoginContract.Effect.GoToBiometricSetup(username, password))\n } else {\n // Not first login or biometric not available - go directly to home\n _effect.tryEmit(LoginContract.Effect.GoToHome)\n }\n }\n }\n }"}"}},{"id":"toolu_014p5rKKhbELEMxvGGLvDBoY","type":"function","function":{"name":"edit","arguments":"{"file_path": "C:/Users/afane/StudioProjects/myfin-android/android/app/src/main/java/com/afaneca/myfin/ui/login/LoginViewModel.kt", "old_string": " fun performBiometricLogin(activity: FragmentActivity) = viewModelScope.launch {\n _mainState.update { it.copy(isLoading = true) }\n\n val credentials = biometricGateway.getBiometricCredentials()\n if (credentials == null) {\n _mainState.update { it.copy(isLoading = false) }\n _effect.tryEmit(LoginContract.Effect.ShowBiometricError)\n return@launch\n }\n\n val authResult = biometricGateway.authenticateWithBiometric(activity)\n\n when (authResult) {\n is BiometricAuthResult.Success -> {\n val params = LoginUseCase.LoginParams(\n username = credentials.username,\n password = authResult.data\n )\n val result = loginUseCase(params)\n _mainState.update { it.copy(isLoading = false) }\n\n when (result) {\n is Result.Error -> handleLoginError(error = result.error)\n is Result.Success -> {\n _effect.tryEmit(LoginContract.Effect.GoToHome)\n }\n }\n }\n BiometricAuthResult.Cancelled -> {\n _mainState.update { it.copy(isLoading = false) }\n // User cancelled, do nothing\n }\n is BiometricAuthResult.EncryptionSuccess -> {\n // This shouldn't happen in login flow, but handle it\n _mainState.update { it.copy(isLoading = false) }\n _effect.tryEmit(LoginContract.Effect.ShowBiometricError)\n }\n is BiometricAuthResult.Failure -> {\n _mainState.update { it.copy(isLoading = false) }\n // Check if key was invalidated\n if (authResult.errorCode == BiometricAuthManager.ERROR_KEY_INVALIDATED) {\n // Biometric credentials were automatically cleared, show special message\n _effect.tryEmit(LoginContract.Effect.ShowBiometricKeyInvalidatedError)\n } else {\n _effect.tryEmit(LoginContract.Effect.ShowBiometricError)\n }\n }\n else -> {\n _mainState.update { it.copy(isLoading = false) }\n _effect.tryEmit(LoginContract.Effect.ShowBiometricError)\n }\n }\n }", "new_string": " fun performBiometricLogin(activity: FragmentActivity) = viewModelScope.launch {\n _mainState.update { it.copy(isLoading = true) }\n\n val credentialsResult = getBiometricCredentialsUseCase(Unit)\n val credentials = when (credentialsResult) {\n is Result.Success -> credentialsResult.data\n is Result.Error -> null\n }\n \n if (credentials == null) {\n _mainState.update { it.copy(isLoading = false) }\n _effect.tryEmit(LoginContract.Effect.ShowBiometricError)\n return@launch\n }\n\n val authUseCaseResult = authenticateWithBiometricUseCase(\n AuthenticateWithBiometricUseCase.Params(activity)\n )\n val authResult = when (authUseCaseResult) {\n is Result.Success -> authUseCaseResult.data\n is Result.Error -> {\n _mainState.update { it.copy(isLoading = false) }\n _effect.tryEmit(LoginContract.Effect.ShowBiometricError)\n return@launch\n }\n }\n\n when (authResult) {\n is BiometricAuthResult.Success -> {\n val params = LoginUseCase.LoginParams(\n username = credentials.username,\n password = authResult.data\n )\n val result = loginUseCase(params)\n _mainState.update { it.copy(isLoading = false) }\n\n when (result) {\n is Result.Error -> handleLoginError(error = result.error)\n is Result.Success -> {\n _effect.tryEmit(LoginContract.Effect.GoToHome)\n }\n }\n }\n BiometricAuthResult.Cancelled -> {\n _mainState.update { it.copy(isLoading = false) }\n // User cancelled, do nothing\n }\n is BiometricAuthResult.EncryptionSuccess -> {\n // This shouldn't happen in login flow, but handle it\n _mainState.update { it.copy(isLoading = false) }\n _effect.tryEmit(LoginContract.Effect.ShowBiometricError)\n }\n is BiometricAuthResult.Failure -> {\n _mainState.update { it.copy(isLoading = false) }\n // Check if key was invalidated\n if (authResult.errorCode == BiometricAuthManager.ERROR_KEY_INVALIDATED) {\n // Biometric credentials were automatically cleared, show special message\n _effect.tryEmit(LoginContract.Effect.ShowBiometricKeyInvalidatedError)\n } else {\n _effect.tryEmit(LoginContract.Effect.ShowBiometricError)\n }\n }\n else -> {\n _mainState.update { it.copy(isLoading = false) }\n _effect.tryEmit(LoginContract.Effect.ShowBiometricError)\n }\n }\n }"}"}}]},{"role":"tool","name":"edit","tool_call_id":"toolu_01WQNcWoLx8ZGhBG689AcLKv","content":"The file C:\Users\afane\StudioProjects\myfin-android\android\app\src\main\java\com\afaneca\myfin\ui\login\LoginViewModel.kt has been updated.

