 2|
 3|import androidx.fragment.app.FragmentActivity
 4|import androidx.lifecycle.ViewModel
 5|import androidx.lifecycle.viewModelScope
 6|import com.afaneca.myfin.domain.common.Result
 7|import com.afaneca.myfin.domain.model.BiometricAuthResult
 8|import com.afaneca.myfin.domain.usecase.CheckBiometricAvailabilityUseCase
 9|import com.afaneca.myfin.domain.usecase.SaveBiometricCredentialsUseCase
 10|import com.afaneca.myfin.ui.common.EffectMutableSharedFlow
 11|import dagger.hilt.android.lifecycle.HiltViewModel
 12|import kotlinx.coroutines.flow.MutableStateFlow
 13|import kotlinx.coroutines.flow.asSharedFlow
 14|import kotlinx.coroutines.flow.asStateFlow
 15|import kotlinx.coroutines.flow.update
 16|import kotlinx.coroutines.launch
 17|import javax.inject.Inject
 18|
 19|@HiltViewModel
 20|class BiometricSetupViewModel @Inject constructor(
 21| private val checkBiometricAvailabilityUseCase: CheckBiometricAvailabilityUseCase,
 22| private val saveBiometricCredentialsUseCase: SaveBiometricCredentialsUseCase,
 23|) : ViewModel(), BiometricSetupContract.ViewModel {
 24|
 25| private val _mainState = MutableStateFlow(BiometricSetupContract.MainState())
 26| override val mainState = _mainState.asStateFlow()
 27|
 28| private val _effect = EffectMutableSharedFlow<BiometricSetupContract.Effect>()
 29| override val effect = _effect.asSharedFlow()
 30|
 31| private var storedUsername: String = ""
 32| private var storedPassword: String = ""
 33|
 34| override fun triggerEvent(event: BiometricSetupContract.Event) {
 35| when (event) {
 36| is BiometricSetupContract.Event.Init -> init(event.username, event.password)
 37| BiometricSetupContract.Event.EnableBiometricClicked -> enableBiometric()
 38| BiometricSetupContract.Event.SkipClicked -> skip()
 39| }
 40| }
 41|
 42| private fun init(username: String, password: String) = viewModelScope.launch {
 43| if (mainState.value.isInitialized) return@launch
 44|
 45| storedUsername = username
 46| storedPassword = password
 47|
 48| val availabilityResult = checkBiometricAvailabilityUseCase(Unit)
 49| val isBiometricAvailable = when (availabilityResult) {
 50| is Result.Success -> availabilityResult.data.canUseBiometric
 51| is Result.Error -> false
 52| }
 53|
 54| _mainState.update {
 55| it.copy(
 56| isInitialized = true,
 57| isBiometricAvailable = isBiometricAvailable
 58| )
 59| }
 60|
 61| // If biometric is not available, skip to home automatically
 62| if (!isBiometricAvailable) {
 63| skip()
 64| }
 65| }
 66|
 67| private fun enableBiometric() {
 68| // This will be called from the UI with the activity reference
 69| // The actual biometric prompt will be triggered from the composable
 70| }
 71|
 72| fun performBiometricSetup(activity: FragmentActivity) = viewModelScope.launch {
 73| _mainState.update { it.copy(isLoading = true) }
 74|
 75| val params = SaveBiometricCredentialsUseCase.Params(
 76| username = storedUsername,
 77| password = storedPassword,
 78| activity = activity
 79| )
 80|
 81| val useCaseResult = saveBiometricCredentialsUseCase(params)
 82| val authResult = when (useCaseResult) {
 83| is Result.Success -> useCaseResult.data
 84| is Result.Error -> {
 85| _mainState.update { it.copy(isLoading = false) }
 86| _effect.tryEmit(BiometricSetupContract.Effect.ShowBiometricError)
 87| return@launch
 88| }
 89| }
 90|
 91| _mainState.update { it.copy(isLoading = false) }
 92|
 93| when (authResult) {
 94| is BiometricAuthResult.Success -> {
 95| _effect.tryEmit(BiometricSetupContract.Effect.GoToHome)
 96| }
 97| is BiometricAuthResult.EncryptionSuccess -> {
