 4|import androidx.lifecycle.ViewModel
 5|import androidx.lifecycle.viewModelScope
 6|import com.afaneca.myfin.domain.common.Result
 7|import com.afaneca.myfin.domain.model.BiometricAuthResult
 8|import com.afaneca.myfin.domain.usecase.CheckBiometricStatusUseCase
 9|import com.afaneca.myfin.domain.usecase.SaveBiometricCredentialsUseCase
 10|import com.afaneca.myfin.ui.common.EffectMutableSharedFlow
 11|import dagger.hilt.android.lifecycle.HiltViewModel
 12|import kotlinx.coroutines.flow.MutableStateFlow
 13|import kotlinx.coroutines.flow.asSharedFlow
 14|import kotlinx.coroutines.flow.asStateFlow
 15|import kotlinx.coroutines.flow.update
 16|import kotlinx.coroutines.launch
 17|import javax.inject.Inject
 18|
 19|@HiltViewModel
 20|class BiometricSetupViewModel @Inject constructor(
 21| private val checkBiometricStatusUseCase: CheckBiometricStatusUseCase,
 22| private val saveBiometricCredentialsUseCase: SaveBiometricCredentialsUseCase,
 23|) : ViewModel(), BiometricSetupContract.ViewModel {
 24|
 25| private val _mainState = MutableStateFlow(BiometricSetupContract.MainState())
 26| override val mainState = _mainState.asStateFlow()
 27|
 28| private val _effect = EffectMutableSharedFlow<BiometricSetupContract.Effect>()
 29| override val effect = _effect.asSharedFlow()
 30|
 31| private var storedUsername: String = ""
 32| private var storedPassword: String = ""
 33|
 34| override fun triggerEvent(event: BiometricSetupContract.Event) {
 35| when (event) {
 36| is BiometricSetupContract.Event.Init -> init(event.username, event.password)
 37| BiometricSetupContract.Event.EnableBiometricClicked -> enableBiometric()
 38| BiometricSetupContract.Event.SkipClicked -> skip()
 39| }
 40| }
 41|
 42| private fun init(username: String, password: String) = viewModelScope.launch {
 43| if (mainState.value.isInitialized) return@launch
 44|
 45| storedUsername = username
 46| storedPassword = password
 47|
 48| val isBiometricAvailable = when (val statusResult = checkBiometricStatusUseCase(Unit)) {
 49| is Result.Success -> statusResult.data.canUseBiometric
 50| is Result.Error -> false
 51| }
 52|
 53| _mainState.update {
 54| it.copy(
 55| isInitialized = true,
 56| isBiometricAvailable = isBiometricAvailable
 57| )
 58| }
 59|
 60| // If biometric is not available, skip to home automatically
 61| if (!isBiometricAvailable) {
 62| skip()
 63| }
 64| }
 65|
 66| private fun enableBiometric() {
 67| // This will be called from the UI with the activity reference
 68| // The actual biometric prompt will be triggered from the composable
 69| }
 70|
 71| fun performBiometricSetup(activity: FragmentActivity) = viewModelScope.launch {
 72| _mainState.update { it.copy(isLoading = true) }
 73|
 74| val params = SaveBiometricCredentialsUseCase.Params(
 75| username = storedUsername,
 76| password = storedPassword,
 77| activity = activity
 78| )
 79|
 80| val useCaseResult = saveBiometricCredentialsUseCase(params)
 81| val authResult = when (useCaseResult) {
 82| is Result.Success -> useCaseResult.data
 83| is Result.Error -> {
 84| _mainState.update { it.copy(isLoading = false) }
 85| _effect.tryEmit(BiometricSetupContract.Effect.ShowBiometricError)
 86| return@launch
 87| }
 88| }
 89|
 90| _mainState.update { it.copy(isLoading = false) }
 91|
 92| when (authResult) {
 93| is BiometricAuthResult.Success -> {
 94| _effect.tryEmit(BiometricSetupContract.Effect.GoToHome)
 95| }
 96| is BiometricAuthResult.EncryptionSuccess -> {
 97| // This shouldn't happen as repository converts it, but handle it anyway
 98| _effect.tryEmit(BiometricSetupContract.Effect.GoToHome)
 99| }
100| BiometricAuthResult.NotAvailable -> {
101| _effect.tryEmit(BiometricSetupContract.Effect.ShowBiometricNotAvailableError)
102| }
103| BiometricAuthResult.NotEnrolled -> {
104| _effect.tryEmit(BiometricSetupContract.Effect.ShowBiometricNotEnrolledError)
105| }
106| BiometricAuthResult.Cancelled -> {
107| // User cancelled, do nothing and let them retry
108| }
109| is BiometricAuthResult.Failure -> {
110| _effect.tryEmit(BiometricSetupContract.Effect.ShowBiometricError)
111| }
112| }
113| }
114|
115| private fun skip() {
116| _effect.tryEmit(BiometricSetupContract.Effect.GoToHome)
117| }
