iometricCredentialsUseCase.SaveResult, SaveBiometricCredentialsUseCase.FeatureError> {\n\n data class Params(\n val username: String,\n val password: String,\n val activity: FragmentActivity\n )\n\n override suspend fun invoke(params: Params): Result<SaveResult, FeatureError> {\n val result = biometricGateway.saveBiometricCredentials(\n username = params.username,\n password = params.password,\n activity = params.activity\n )\n \n // Map data layer result to domain-specific result\n val domainResult = when (result) {\n is BiometricAuthResult.Success,\n is BiometricAuthResult.EncryptionSuccess -> SaveResult.Success\n BiometricAuthResult.NotAvailable -> SaveResult.NotAvailable\n BiometricAuthResult.NotEnrolled -> SaveResult.NotEnrolled\n BiometricAuthResult.Cancelled -> SaveResult.Cancelled\n is BiometricAuthResult.Failure -> SaveResult.Failure(result.reason)\n }\n \n return Result.Success(domainResult)\n }\n\n sealed interface SaveResult {\n data object Success : SaveResult\n data object NotAvailable : SaveResult\n data object NotEnrolled : SaveResult\n data object Cancelled : SaveResult\n data class Failure(val reason: String? = null) : SaveResult\n }\n\n sealed interface FeatureError {\n data object GenericError : FeatureError\n }\n}"}"}},{"id":"toolu_019mwN2t8C3zkAw1jg9ZaAbe","type":"function","function":{"name":"edit","arguments":"{"file_path": "C:/Users/afane/StudioProjects/myfin-android/android/app/src/main/java/com/afaneca/myfin/domain/usecase/AuthenticateWithBiometricUseCase.kt", "old_string": "package com.afaneca.myfin.domain.usecase\n\nimport androidx.fragment.app.FragmentActivity\nimport com.afaneca.myfin.domain.common.Result\nimport com.afaneca.myfin.domain.model.BiometricAuthResult\nimport com.afaneca.myfin.domain.repository.BiometricGateway\nimport javax.inject.Inject\n\nclass AuthenticateWithBiometricUseCase @Inject constructor(\n private val biometricGateway: BiometricGateway,\n) : BaseUseCase<AuthenticateWithBiometricUseCase.Params, BiometricAuthResult, AuthenticateWithBiometricUseCase.FeatureError> {\n\n data class Params(val activity: FragmentActivity)\n\n override suspend fun invoke(params: Params): Result<BiometricAuthResult, FeatureError> {\n val result = biometricGateway.authenticateWithBiometric(params.activity)\n \n // EncryptionSuccess shouldn't occur in authentication flow, but if it does,\n // treat it as an error since we expect Success with decrypted password\n val domainResult = when (result) {\n is BiometricAuthResult.EncryptionSuccess -> {\n BiometricAuthResult.Failure(\"Unexpected encryption result in authentication flow\")\n }\n else -> result\n }\n \n return Result.Success(domainResult)\n }\n\n sealed interface FeatureError {\n data object GenericError : FeatureError\n }\n}", "new_string": "package com.afaneca.myfin.domain.usecase\n\nimport androidx.fragment.app.FragmentActivity\nimport com.afaneca.myfin.domain.common.Result\nimport com.afaneca.myfin.domain.model.BiometricAuthResult\nimport com.afaneca.myfin.domain.repository.BiometricGateway\nimport javax.inject.Inject\n\nclass AuthenticateWithBiometricUseCase @Inject constructor(\n private val biometricGateway: BiometricGateway,\n) : BaseUseCase<AuthenticateWithBiometricUseCase.Params, AuthenticateWithBiometricUseCase.AuthResult, AuthenticateWithBiometricUseCase.FeatureError> {\n\n data class Params(val activity: FragmentActivity)\n\n override suspend fun invoke(params: Params): Result<AuthResult, FeatureError> {\n val result = biometricGateway.authenticateWithBiometric(params.activity)\n \n // Map data layer result to domain-specific result\n val domainResult = when (result) {\n is BiometricAuthResult.Success -> AuthResult.Success(result.data)\n BiometricAuthResult.Cancelled -> AuthResult.Cancelled\n is BiometricAuthResult.Failure -> AuthResult.Failure(\n reason = result.reason,\n errorCode = result.errorCode\n )\n // These shouldn't occur in authentication flow\n BiometricAuthResult.NotAvailable,\n BiometricAuthResult.NotEnrolled,\n is Bi