import com.afaneca.myfin.domain.common.Result
import com.afaneca.myfin.domain.model.BiometricCredentials
import com.afaneca.myfin.domain.repository.BiometricGateway
import javax.inject.Inject

class GetBiometricCredentialsUseCase @Inject constructor(
 private val biometricGateway: BiometricGateway,
) : BaseUseCase<Unit, BiometricCredentials?, GetBiometricCredentialsUseCase.FeatureError> {

 override suspend fun invoke(params: Unit): Result<BiometricCredentials?, FeatureError> {
 return Result.Success(biometricGateway.getBiometricCredentials())
 }

 sealed interface FeatureError {
 data object GenericError : FeatureError
 }
}
