========\n\n @Test\n fun `initial state has start route as top level`() {\n assertEquals(Login, navigationState.topLevelRoute)\n assertEquals(listOf(Login), navigationState.topLevelHistory)\n }\n\n @Test\n fun `initial state has start route in its backstack`() {\n val loginStack = navigationState.backStacks[Login]!!\n assertEquals(1, loginStack.size)\n assertEquals(Login, loginStack.items[0])\n }\n\n // ========== Basic Navigation Tests ==========\n\n @Test\n fun `navigate to top-level route adds to history`() {\n // Navigate from Login to Home\n navigator.navigate(Home, removeCurrentFromBackStack = false)\n\n assertEquals(Home, navigationState.topLevelRoute)\n assertEquals(listOf(Login, Home), navigationState.topLevelHistory)\n }\n\n @Test\n fun `navigate with removeCurrentFromBackStack replaces in history`() {\n // Navigate from Login to Home, removing Login\n navigator.navigate(Home, removeCurrentFromBackStack = true)\n\n assertEquals(Home, navigationState.topLevelRoute)\n assertEquals(listOf(Home), navigationState.topLevelHistory)\n }\n\n @Test\n fun `navigate to same top-level route does not add to history`() {\n navigator.navigate(Home, removeCurrentFromBackStack = true)\n val historyBefore = navigationState.topLevelHistory.toList()\n\n // Navigate to Home again\n navigator.navigate(Home, removeCurrentFromBackStack = false)\n\n assertEquals(Home, navigationState.topLevelRoute)\n assertEquals(historyBefore, navigationState.topLevelHistory)\n }\n\n // ========== Back Navigation Tests ==========\n\n @Test\n fun `goBack from top-level route navigates to previous in history`() {\n // Setup: Home -> Transactions\n navigator.navigate(Home, removeCurrentFromBackStack = true)\n navigator.navigate(Transactions, removeCurrentFromBackStack = false)\n\n // Go back from Transactions\n val canGoBack = navigator.goBack()\n\n assertTrue(canGoBack)\n assertEquals(Home, navigationState.topLevelRoute)\n assertEquals(listOf(Home), navigationState.topLevelHistory)\n }\n\n @Test\n fun `goBack from start route returns false`() {\n // At Login (start route)\n val canGoBack = navigator.goBack()\n\n assertFalse(canGoBack)\n assertEquals(Login, navigationState.topLevelRoute)\n }\n\n @Test\n fun `goBack from single item history returns false`() {\n // Navigate to Home (replacing Login)\n navigator.navigate(Home, removeCurrentFromBackStack = true)\n\n // Try to go back from Home (only item in history)\n val canGoBack = navigator.goBack()\n\n assertFalse(canGoBack)\n assertEquals(Home, navigationState.topLevelRoute)\n assertEquals(listOf(Home), navigationState.topLevelHistory)\n }\n\n // ========== Complex Flow Tests ==========\n\n @Test\n fun `user scenario - login to home to transactions and back`() {\n // This is the exact scenario from the bug report\n \n // 1. Login -> Home (with removeCurrentFromBackStack)\n navigator.navigate(Home, removeCurrentFromBackStack = true)\n assertEquals(Home, navigationState.topLevelRoute)\n assertEquals(listOf(Home), navigationState.topLevelHistory)\n\n // 2. Home -> Transactions (via nav drawer)\n navigator.navigate(Transactions, removeCurrentFromBackStack = false)\n assertEquals(Transactions, navigationState.topLevelRoute)\n assertEquals(listOf(Home, Transactions), navigationState.topLevelHistory)\n\n // 3. Back gesture -> Should go to Home\n val canGoBack1 = navigator.goBack()\n assertTrue(\"Should be able to go back from Transactions\", canGoBack1)\n assertEquals(Home, navigationState.topLevelRoute)\n assertEquals(listOf(Home), navigationState.topLevelHistory)\n\n // 4. Back gesture from Home -> Should exit (return false)\n val canGoBack2 = navigator.goBack()\n assertFalse(\"Should not be able to go back from Home\", canGoBack2)\n }\n\n @Test\n fun `complex navigation flow works correctly`() {\n // Scenario: Login -> Home -> Transactions -> Settings -> Back -> Back -> Back\n \n // Login -> Home (replace)\n navigator.navigate(Home, removeCurrentFromBackStack = true)\n assertEquals(listOf(Home), navigationState.topLevelHistory)\n\n // Home -> Transactions\n navigator.navigate(Transactions, removeCurrentFromBackStack = false)\n assertEquals(listOf(Home, Transactions), navigationState.topLevelHistory)\n\n // Transactions -> Settings\n navigator.navigate(Settings, removeCurrentFromBackStack = false)\n assertEquals(listOf(Home, Transactions, Settings), navigationState.topLevelHistory)\n\n // Back: Settings -> Transactions\n assertTrue(navigator.goBack())\n assertEquals(Transactions, navigationState.topLevelRoute)\n assertEquals(listOf(Home, Transactions), navigationState.topLevelHistory)\n\n // Back: Transactions -> Home\n assertTrue(navigator.goBack())\n assertEquals(Home, navigationState.topLevelRoute)\n assertEquals(listOf(Home), navigationState.topLevelHistory)\n\n // Back: Home -> Exit (can't go back)\n assertFalse(navigator.goBack())\n }\n\n @Test\n fun `multiple back and forth navigations maintain history correctly`() {\n // Home -> Transactions -> Home -> Transactions\n navigator.navigate(Home, removeCurrentFromBackStack = true)\n navigator.navigate(Transactions)\n navigator.navigate(Home)\n navigator.navigate(Transactions)\n\n // History should be: [Home, Transactions, Home, Transactions]\n assertEquals(listOf(Home, Transactions, Home, Transactions), navigationState.topLevelHistory)\n\n // Back 3 times should go: Transactions -> Home -> Transactions -> Home\n assertTrue(navigator.goBack())\n assertEquals(Home, navigationState.topLevelRoute)\n\n assertTrue(navigator.goBack())\n assertEquals(Transactions, navigationState.topLevelRoute)\n\n assertTrue(navigator.goBack())\n assertEquals(Home, navigationState.topLevelRoute)\n\n // Can't go back anymore\n assertFalse(navigator.goBack())\n }\n\n @Test\n fun `navigate between all top level routes builds correct history`() {\n navigator.navigate(Home, removeCurrentFromBackStack = true)\n navigator.navigate(Transactions)\n navigator.navigate(Settings)\n \n assertEquals(listOf(Home, Transactions, Settings), navigationState.topLevelHistory)\n assertEquals(Settings, navigationState.topLevelRoute)\n }\n\n // ========== State Consistency Tests ==========\n\n @Test\n fun `stacksInUse returns topLevelHistory`() {\n navigator.navigate(Home, removeCurrentFromBackStack = true)\n navigator.navigate(Transactions)\n\n assertEquals(listOf(Home, Transactions), navigationState.stacksInUse)\n }\n\n @Test\n fun `currentRoute returns last item in current stack`() {\n navigator.navigate(Home, removeCurrentFromBackStack = true)\n assertEquals(Home, navigationState.currentRoute)\n }\n\n @Test\n fun `removeCurrentFromBackStack actually removes from stack`() {\n val loginStack = navigationState.backStacks[Login]!!\n assertEquals(1, loginStack.size) // [Login]\n\n // Navigate to Home with removeCurrentFromBackStack\n navigator.navigate(Home, removeCurrentFromBackStack = true)\n\n // Login stack should be empty now\n assertEquals(0, loginStack.size)\n }\n\n /**\n * Test implementation of NavigationState that doesn't require Compose\n */\n private class TestNavigationState(\n startRoute: NavKey,\n topLevelRoutes: Set<NavKey>\n ) : NavigationState(\n startRoute = startRoute,\n topLevelRoute = mutableStateOf(startRoute),\n topLevelHistory = mutableStateOf(listOf(startRoute)),\n backStacks = topLevelRoutes.associateWith { TestNavBackStack(it) }\n )\n\n /**\n * Test implementation of NavBackStack\n */\n private class TestNavBackStack(initialRoute: NavKey) : androidx.navigation3.runtime.NavBackStack<NavKey> {\n val items = mutableListOf(initialRoute)\n \n val size: Int get() = items.size\n\n override fun add(key: NavKey): Boolean {\n items.add(key)\n return true\n }\n\n override fun contains(element: NavKey): Boolean = items.contains(element)\n\n override fun containsAll(elements: Collection<NavKey>): Boolean = items.containsAll(elements)\n\n override fun isEmpty(): Boolean = items.isEmpty()\n\n override fun iterator(): Iterator<NavKey> = items.iterator()\n\n override val size: Int get() = items.size\n\n override fun last(): NavKey = items.last()\n\n override fun lastOrNull(): NavKey? = items.lastOrNull()\n\n override fun removeLastOrNull(): NavKey? {\n return if (items.size > 1) items.removeAt(items.lastIndex) else null\n }\n\n override fun toString(): String = items.toString()\n }\n}\n"}"}}]},{"role":"tool","name":"write","tool_call_id":"toolu_01FgzGWsSakGgeyV7pfn2deR","content":"Wrote contents to C:\Users\afane\StudioProjects\myfin-android\android\app\src\test\java\com\afaneca\myfin\ui\common\nav\NavigatorTest.kt.

