import kotlinx.serialization.Serializable

sealed interface AppRoute : NavKey {
 @Serializable
 data object Login : AppRoute

 @Serializable
 data class BiometricSetup(val username: String, val password: String) : AppRoute

 @Serializable
 data object Onboarding : AppRoute

 @Serializable
 data object Settings : AppRoute

 @Serializable
 data object Home : AppRoute

 @Serializable
 data object Transactions : AppRoute
}

@AndroidEntryPoint
class MainActivity : FragmentActivity() {

 override fun onCreate(savedInstanceState: Bundle?) {
 super.onCreate(savedInstanceState)
 enableEdgeToEdge()
 setContent {
 val viewModel: MainViewModel = hiltViewModel()
 val lifecycleOwner = LocalLifecycleOwner.current
 val uiState by viewModel.mainState.collectAsStateWithLifecycle()
 val navigationState = rememberNavigationState(
 startRoute = AppRoute.Login,
 topLevelRoutes = setOf(
 AppRoute.Login,
 AppRoute.BiometricSetup("", ""),
 AppRoute.Home,
 AppRoute.Transactions,
 ),
 )

 val navigator = remember { Navigator(navigationState) }

 val isPrivateRoute = when (navigationState.topLevelRoute) {
 AppRoute.Login, AppRoute.Settings, AppRoute.Onboarding, is AppRoute.BiometricSetup -> false
 else -> true
 }

 val drawerState = rememberDrawerState(DrawerValue.Closed)
 val scope = rememberCoroutineScope()

 LaunchedEffect(Unit) {
 viewModel.triggerEvent(MainContract.Event.Init)

 viewModel.effect.flowWithLifecycle(
 lifecycleOwner.lifecycle,
 Lifecycle.State.STARTED,
 )
 .onEach { effect ->
 when (effect) {
 MainContract.Effect.OpenNavigationDrawer -> {
 drawerState.open()
 }

 MainContract.Effect.GoToLogin -> {
 navigator.navigate(
 route = AppRoute.Login,
 removeCurrentFromBackStack = true,
 )
 }
 }
 }.launchIn(this)
 }

 fun openNavigationDrawer() {
 viewModel.triggerEvent(MainContract.Event.NavDrawerIconClicked)
 }

 AppTheme(
 dynamicColor = uiState.useDynamicTheme,
 ) {

 CompositionLocalProvider(
 LocalLoadingState provides MainContract.LoadingState(
 isLoading = uiState.isLoading,
 setLoading = { viewModel.triggerEvent(MainContract.Event.UpdateLoading(it)) },
 ),
 ) {
 Box(modifier = Modifier.fillMaxSize()) {
 MFModalNavigationDrawer(
 drawerState = drawerState,
 gesturesEnabled = isPrivateRoute,
 balanceDigest = uiState.balanceDigest,
 itemContent = {
 NavigationDrawerItem(
 icon = {
 Icon(
 painter = painterResource(R.drawable.dashboard_24),
 contentDescription = stringResource(R.string.dashboard),
 )
 },
 label = { Text(stringResource(R.string.dashboard)) },
 selected = navigationState.currentRoute == AppRoute.Home,
 onClick = {
 navigator.navigate(AppRoute.Home)
 scope.launch { drawerState.close() }
 },
 )
 NavigationDrawerItem(
 icon = {
 Icon(
 painter = painterResource(R.drawable.list_alt_24),
 contentDescription = stringResource(R.string.transactions),
 )
 },
 label = { Text(stringResource(R.string.transactions)) },
 selected = navigationState.currentRoute == AppRoute.Transactions,
 onClick = {
 navigator.navigate(AppRoute.Transactions)
 scope.launch { drawerState.close() }
 },
 )
 NavigationDrawerItem(
 icon = {
 Icon(
 painter = painterResource(R.drawable.logout_24),
 contentDescription = stringResource(R.string.logout),
 )
 },
 label = { Text(stringResource(R.string.logout)) },
 selected = false,
 onClick = {
 viewModel.triggerEvent(MainContract.Event.LogoutClicked)
 scope.launch { drawerState.close() }
 },
 colors = NavigationDrawerItemDefaults.colors(
 unselectedTextColor = MaterialTheme.colorScheme.error,
 unselectedIconColor = MaterialTheme.colorScheme.error,
 ),
 )
 },
 ) {
 val entryProvider = entryProvider {
 publicNav(navigator = navigator)
 privateNav(
 openNavigationDrawer = { openNavigationDrawer() },
 goToSettings = { navigator.navigate(AppRoute.Settings) },
 goToTransactions = { navigator.navigate(AppRoute.Transactions) },
 goToAccounts = { /* TODO */ },
 goToBudgets = { /* TODO */ },
 )
 }

 MFNavDisplay(
 entries = navigationState.toEntries(entryProvider),
 onBack = {
 if (drawerState.isOpen) {
 scope.launch { drawerState.close() }
 return@MFNavDisplay
 }
 if (!navigator.goBack()) {
 finish()
 }
 },
 )
 }

 GlobalLoadingOverlay(isLoading = uiState.isLoading)
 }
 }
 }
 }
 }

 private fun EntryProviderScope<NavKey>.publicNav(navigator: Navigator) {
 entry<AppRoute.Login> { key ->
 LoginScreen(
 goToHome = {
 navigator.navigate(route = AppRoute.Home, removeCurrentFromBackStack = true)
 },
 goToBiometricSetup = { username, password ->
 navigator.navigate(
 route = AppRoute.BiometricSetup(username, password),
 removeCurrentFromBackStack = true,
 )
 },
 showError = {},
 goToSettings = { navigator.navigate(AppRoute.Settings) },
 )
 }

 entry<AppRoute.BiometricSetup> { key ->
 BiometricSetupScreen(
 username = key.username,
 password = key.password,
 goToHome = {
 navigator.navigate(route = AppRoute.Home, removeCurrentFromBackStack = true)
 },
 )
 }

 entry<AppRoute.Settings> { key ->
 SettingsScreen()
 }
 }

 private fun EntryProviderScope<NavKey>.privateNav(
 openNavigationDrawer: () -> Unit,
 goToSettings: () -> Unit,
 goToTransactions: () -> Unit,
 goToAccounts: () -> Unit,
 goToBudgets: () -> Unit,
 ) {
 entry<AppRoute.Home> { key ->
 DashboardScreen(
 openNavigationDrawer = openNavigationDrawer,
 goToSettings = goToSettings,
 goToTransactions = goToTransactions,
 goToAccounts = goToAccounts,
 goToBudgets = goToBudgets,
 )
 }
 entry<AppRoute.Transactions> { key ->
 TransactionListScreen(
 openNavigationDrawer = openNavigationDrawer,
 goToSettings = goToSettings,
 )
 }
 }
}
","ranges":[],"type":"current_file"},{"file_path":"app/src/main/java/com/afaneca/myfin/ui/common/nav/Navigator.kt","code_text":"package com.afaneca.myfin.ui.common.nav

import androidx.navigation3.runtime.NavKey

/**
 * Handles navigation events (forward and back) by updating the navigation state.
 */
class Navigator(val state: NavigationState) {
 fun navigate(
 route: NavKey,
 removeCurrentFromBackStack: Boolean = false,
 forceAdd: Boolean = false
 ) {
 if (removeCurrentFromBackStack) {
 state.backStacks[state.topLevelRoute]?.removeLastOrNull()
 }

 if (!forceAdd && route in state.backStacks.keys) {
 // This is a top level route, just switch to it.
 if(state.backStacks[route]?.isEmpty() == true){
 state.backStacks[route]?.add(route)
 }

 // Update top-level history if switching to a different top-level route
 if (state.topLevelRoute != route) {
 if (removeCurrentFromBackStack) {
 // Replace current top-level route in history with the new one
 state.topLevelHistory = state.topLevelHistory.dropLast(1) + route
 } else {
 // Add new top-level route to history
 state.topLevelHistory += route
 }
 }

 state.topLevelRoute = route
 } else {
 state.backStacks[state.topLevelRoute]?.add(route)
 }
 }

 /**
 * Tries to go back in the backstack. If it can't (already at the start route), it returns false.
 * Returns true otherwise.
 */
 fun goBack(): Boolean {
 val currentStack = state.backStacks[state.topLevelRoute]
 ?: error("Stack for ${state.topLevelRoute} not found")
 val currentRoute = currentStack.last()

 return when (currentRoute) {
 state.startRoute -> {
 // If we're already at the start route, then we can't go back.
 false
 }

 state.topLevelRoute -> {
 // If we're at the base of the current top-level route, check top-level history
 if (state.topLevelHistory.size > 1) {
 // Remove current from history and navigate to previous top-level route
 val newHistory = state.topLevelHistory.dropLast(1)
 val previousTopLevel = newHistory.last()
 state.topLevelHistory = newHistory
 state.topLevelRoute = previousTopLevel
 return true
 } else {
 // No top-level history, can't go back
 return false
 }
 }

 else -> {
 val result = currentStack.removeLastOrNull()
 return result != null
 }
 }
 }
}
